((SELECT id FROM learning_modules WHERE slug = 'quant'), 'trains', 'Problems on Trains', 'A train crossing a pole/person covers its own length; crossing a platform/bridge/another train covers the sum of lengths.', 12),
((SELECT id FROM learning_modules WHERE slug = 'quant'), 'boats-and-streams', 'Boats and Streams', 'Downstream the stream helps the boat; upstream the stream opposes it.', 13),
((SELECT id FROM learning_modules WHERE slug = 'quant'), 'probability', 'Probability', 'Probability = favourable outcomes / total equally likely outcomes.', 14),
