INSERT INTO lessons (topic_id, title, content, difficulty, est_minutes, sort_order) VALUES
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'number-systems'), 'Number Systems', '{"explanation":"Number systems questions test divisibility, remainders, unit digits and factors. Natural numbers start at 1, whole numbers at 0. Integers include negatives. A prime has exactly two factors.","formulas":["Sum of first n natural numbers = n(n+1)/2","Sum of first n odd numbers = n²","Sum of squares = n(n+1)(2n+1)/6","If N = p^a × q^b × r^c, number of factors = (a+1)(b+1)(c+1)","Dividend = Divisor × Quotient + Remainder"],"shortcuts":["Divisible by 3/9: digit sum divisible by 3/9","Divisible by 4: last two digits divisible by 4; by 8: last three digits","Divisible by 11: difference of alternate digit sums is 0 or a multiple of 11","Unit digits of powers repeat every 4: find n mod 4","Highest power of p in n! = floor(n/p) + floor(n/p²) + ..."],"solved_examples":[{"question":"Find the unit digit of 7^95.","solution":"Cycle of 7: 7, 9, 3, 1 (length 4). 95 mod 4 = 3 → third term = 3."},{"question":"How many factors does 360 have?","solution":"360 = 2³ × 3² × 5¹ → (3+1)(2+1)(1+1) = 24 factors."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'hcf-and-lcm'), 'HCF and LCM', '{"explanation":"HCF (Highest Common Factor) is the largest number dividing all given numbers; LCM (Least Common Multiple) is the smallest number divisible by all of them. Use prime factorisation or the division method.","formulas":["HCF × LCM = product of two numbers","HCF of fractions = HCF of numerators / LCM of denominators","LCM of fractions = LCM of numerators / HCF of denominators"],"shortcuts":["Bells/lights together again → LCM","Largest tile, largest container, greatest divisor → HCF","Least number leaving the same remainder r → LCM + r","Greatest number leaving remainders r1, r2 → HCF(a - r1, b - r2)"],"solved_examples":[{"question":"Find the least number which when divided by 12, 15 and 20 leaves remainder 5.","solution":"LCM(12, 15, 20) = 60. Answer = 60 + 5 = 65."},{"question":"Product of two numbers is 2160 and HCF is 12. Find LCM.","solution":"LCM = 2160/12 = 180."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'percentages'), 'Percentages', '{"explanation":"Percent means \"per hundred\". Percentages compare quantities and describe increase or decrease.","formulas":["x% of y = xy/100","% change = (new - old)/old × 100","Successive changes a% and b%: a + b + ab/100","If price rises by r%, cut consumption by r/(100 + r) × 100% to keep expenditure same"],"shortcuts":["Memorise fractions: 1/8 = 12.5%, 1/6 = 16.67%, 1/3 = 33.33%, 1/12 = 8.33%","If A is r% more than B, B is r/(100 + r) × 100% less than A","+x% then -x% always gives a net loss of x²/100 %"],"solved_examples":[{"question":"A salary is raised 20% then cut 20%. Net change?","solution":"20 - 20 - 400/100 = -4% → 4% decrease."},{"question":"Price rises 25%. Reduce consumption by?","solution":"25/125 × 100 = 20%."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'profit-and-loss'), 'Profit and Loss', '{"explanation":"Cost Price (CP) is what you pay; Selling Price (SP) is what you receive. Marked Price (MP) is the tagged price before discount. Profit/loss % is always on CP; discount % is always on MP.","formulas":["Profit% = (SP - CP)/CP × 100","SP = CP × (100 + gain%)/100","SP = MP × (100 - discount%)/100","False weight gain% = error/(true value - error) × 100"],"shortcuts":["Same SP, x% gain on one and x% loss on other → loss of x²/100 %","CP of x articles = SP of y articles → gain% = (x - y)/y × 100","Successive discounts a% and b% = a + b - ab/100"],"solved_examples":[{"question":"MP is 40% above CP, discount 10%. Profit%?","solution":"CP 100 → MP 140 → SP 126 → profit 26%."},{"question":"A dealer uses 900 g for 1 kg. Gain%?","solution":"100/900 × 100 = 11.11%."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'simple-interest'), 'Simple Interest', '{"explanation":"Simple interest is calculated only on the original principal every year.","formulas":["SI = P × R × T/100","Amount = P + SI","R = SI × 100/(P × T)","Sum doubles in T years → R = 100/T"],"shortcuts":["If a sum becomes k times in t years, it becomes m times in t(m - 1)/(k - 1) years","SI for each year is the same, so interest grows linearly"],"solved_examples":[{"question":"At what rate does a sum double in 8 years (SI)?","solution":"R = 100/8 = 12.5%."},{"question":"SI on ₹5000 at 8% for 3 years?","solution":"5000 × 8 × 3/100 = ₹1200."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'compound-interest'), 'Compound Interest', '{"explanation":"In compound interest, interest is added to the principal and the next interest is calculated on the new amount.","formulas":["A = P(1 + R/100)^n","CI = A - P","Half-yearly: rate R/2, periods 2n","CI - SI (2 years) = P(R/100)²","CI - SI (3 years) = P(R/100)²(3 + R/100)"],"shortcuts":["10% for 2 years ⇒ multiply by 1.21; 3 years ⇒ 1.331","If a sum doubles in n years, it becomes 2^k times in kn years","Effective rate for 2 years at r% = 2r + r²/100"],"solved_examples":[{"question":"CI on ₹10000 at 10% for 2 years?","solution":"10000 × 1.21 - 10000 = ₹2100."},{"question":"CI - SI for 2 years at 5% on ₹8000?","solution":"8000 × (0.05)² = ₹20."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'ratio-and-proportion'), 'Ratio and Proportion', '{"explanation":"A ratio compares two quantities of the same kind. A proportion states that two ratios are equal (a:b = c:d).","formulas":["a:b = c:d ⇒ ad = bc","Fourth proportional of a, b, c = bc/a","Mean proportional of a and b = √(ab)","Third proportional of a and b = b²/a","A:B = a:b and B:C = c:d ⇒ A:B:C = ac:bc:bd"],"shortcuts":["Write unknown quantities as ax and bx","For dividing amounts, share = part/total × amount"],"solved_examples":[{"question":"Divide ₹1200 in the ratio 3:5.","solution":"1200/8 = 150 → ₹450 and ₹750."},{"question":"Mean proportional of 9 and 16?","solution":"√144 = 12."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'averages'), 'Averages', '{"explanation":"Average = sum of observations / number of observations. Questions often add or remove items and ask how the average changes.","formulas":["Average = Sum/n","Average of first n natural numbers = (n + 1)/2","New member''s value = new avg + n × change (when the group grows from n to n+1)","Combined average = (n1a1 + n2a2)/(n1 + n2)"],"shortcuts":["Average of consecutive numbers = (first + last)/2","If each value increases by k, the average increases by k","Batsman: new average = score - (innings - 1) × increase"],"solved_examples":[{"question":"Average of 30 students is 14. With the teacher, average is 15. Teacher''s age?","solution":"15 × 31 - 14 × 30 = 465 - 420 = 45."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'mixtures'), 'Mixtures and Alligation', '{"explanation":"Alligation finds the ratio in which two ingredients at different prices/concentrations must be mixed to get a desired mean value.","formulas":["Cheaper : Dearer = (d - m) : (m - c)","Repeated replacement: final = initial × (1 - x/V)^n"],"shortcuts":["Draw the alligation cross with c and d on top, m in the middle","Quantity that does not change (e.g. milk when adding water) is the anchor"],"solved_examples":[{"question":"Mix rice at ₹40 and ₹60 to get ₹46. Ratio?","solution":"(60 - 46):(46 - 40) = 14:6 = 7:3."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'time-and-work'), 'Time and Work', '{"explanation":"Work questions use rates. If A finishes work in a days, A does 1/a of the work per day. Rates add when people work together.","formulas":["Together: 1/a + 1/b ⇒ time = ab/(a + b)","M1 × D1 × H1 = M2 × D2 × H2 (for the same work)","B alone = at/(a - t) when A alone = a and together = t"],"shortcuts":["LCM method: take total work = LCM of days; each person''s efficiency = work/days","Efficiency is inversely proportional to time"],"solved_examples":[{"question":"A: 12 days, B: 24 days. Together?","solution":"12×24/36 = 8 days."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'pipes-and-cisterns'), 'Pipes and Cisterns', '{"explanation":"Identical to time and work: inlet pipes do positive work, outlet pipes or leaks do negative work.","formulas":["Fill in a hours, empty in b hours (b > a): net time = ab/(b - a)","Two inlets: ab/(a + b)"],"shortcuts":["Use LCM of all times as tank capacity in units","Subtract the rate of leaks/outlets"],"solved_examples":[{"question":"Pipe fills in 6 h, leak empties in 12 h. Time?","solution":"6×12/(12 - 6) = 12 hours."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'time-speed-distance'), 'Time, Speed and Distance', '{"explanation":"Distance = Speed × Time. Use relative speed when two objects move towards or away from each other.","formulas":["km/h → m/s: × 5/18; m/s → km/h: × 18/5","Average speed (equal distances) = 2xy/(x + y)","Opposite direction relative speed = a + b; same direction = a - b"],"shortcuts":["If speed ratio is a:b, time ratio is b:a for the same distance","Late/early problems: difference in time × product of speeds/difference of speeds = distance"],"solved_examples":[{"question":"Average speed at 40 and 60 km/h for equal distances?","solution":"2×40×60/100 = 48 km/h."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'trains'), 'Problems on Trains', '{"explanation":"A train crossing a pole/person covers its own length; crossing a platform/bridge/another train covers the sum of lengths.","formulas":["Time = (L1 + L2)/relative speed","Pole: time = length/speed"],"shortcuts":["Convert km/h to m/s first: 36 → 10, 54 → 15, 72 → 20, 90 → 25, 108 → 30"],"solved_examples":[{"question":"200 m train at 72 km/h crosses a 300 m platform. Time?","solution":"500/20 = 25 s."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'boats-and-streams'), 'Boats and Streams', '{"explanation":"Downstream the stream helps the boat; upstream the stream opposes it.","formulas":["Downstream = b + s; Upstream = b - s","b = (D + U)/2; s = (D - U)/2"],"shortcuts":["If upstream takes k times as long, b = s(k + 1)/(k - 1)"],"solved_examples":[{"question":"Down 14 km/h, up 8 km/h. Boat & stream speed?","solution":"b = 11, s = 3 km/h."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'probability'), 'Probability', '{"explanation":"Probability = favourable outcomes / total equally likely outcomes. It always lies between 0 and 1.","formulas":["P(not A) = 1 - P(A)","P(A or B) = P(A) + P(B) - P(A and B)","Independent events: P(A and B) = P(A) × P(B)","At least one = 1 - P(none)"],"shortcuts":["Two dice → 36 outcomes; sum 7 has the most (6) ways","Deck: 52 cards, 4 suits, 12 face cards, 26 red"],"solved_examples":[{"question":"Two dice: P(sum = 8)?","solution":"(2,6),(3,5),(4,4),(5,3),(6,2) → 5/36."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'permutations-and-combinations'), 'Permutations and Combinations', '{"explanation":"Permutation = arrangement (order matters). Combination = selection (order does not matter).","formulas":["nPr = n!/(n - r)!","nCr = n!/(r!(n - r)!)","Arrangements with repeats = n!/(p! q! ...)","Circular arrangements = (n - 1)!","Diagonals of n-gon = n(n - 3)/2"],"shortcuts":["\"Together\" → treat as one block; multiply by internal arrangements","\"At least one\" → total - none","nCr = nC(n - r)"],"solved_examples":[{"question":"Arrangements of BANANA?","solution":"6!/(3! 2!) = 60."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'ages'), 'Problems on Ages', '{"explanation":"Translate statements into equations. The age difference between two people never changes.","formulas":["If present age is x, after n years = x + n, n years ago = x - n"],"shortcuts":["Use ratio multipliers (ax, bx)","Check answers by substituting back — fastest in MCQs"],"solved_examples":[{"question":"Ratio 3:5 now, 5:7 after 6 years. Ages?","solution":"(3x+6)/(5x+6) = 5/7 → x = 6 → 18 and 30."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'partnership'), 'Partnership', '{"explanation":"Profit is shared in the ratio of capital × time invested by each partner.","formulas":["Share ratio = C1T1 : C2T2 : ..."],"shortcuts":["Same time period → ratio of capitals only","Late joiner invests for (12 - months late) months"],"solved_examples":[{"question":"A ₹5000 for 12 m, B ₹6000 for 10 m. Ratio?","solution":"60000:60000 = 1:1."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'mensuration'), 'Mensuration', '{"explanation":"Mensuration covers perimeter, area, surface area and volume of 2D and 3D shapes.","formulas":["Rectangle area = lb; perimeter = 2(l + b)","Circle area = πr²; circumference = 2πr","Cylinder volume = πr²h; CSA = 2πrh","Cone volume = (1/3)πr²h","Sphere volume = (4/3)πr³; surface = 4πr²","Cube: volume a³, TSA 6a²"],"shortcuts":["% change in area when both sides change by x% = 2x + x²/100","Use radius in multiples of 7 with π = 22/7"],"solved_examples":[{"question":"Cylinder r = 7, h = 10. Volume?","solution":"22/7 × 49 × 10 = 1540 cm³."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'quant' AND t.slug = 'data-interpretation'), 'Data Interpretation', '{"explanation":"DI presents data in tables, bar charts, pie charts or line graphs and asks calculation questions. Speed and approximation matter.","formulas":["% change = (new - old)/old × 100","Share % = part/total × 100","Average = total/count"],"shortcuts":["Read the question first, then only the data you need","Approximate when options are far apart","Watch units (thousands, lakhs, %)"],"solved_examples":[{"question":"Sales 120 → 150. % increase?","solution":"30/120 × 100 = 25%."}],"practice_note":"Practise this topic with timed quizzes (Easy, Medium and Hard) using the Practice button."}'::jsonb, 'easy', 25, 0);
INSERT INTO learning_topics (module_id, slug, title, summary, sort_order) VALUES
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'number-series', 'Number Series', 'Find the rule that generates the sequence, then apply it to find the next or the wrong term.', 0),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'alphabet-series', 'Alphabet Series', 'Letters follow position-based patterns.', 1),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'coding-and-decoding', 'Coding and Decoding', 'A word is converted to a code using a hidden rule (letter shift, reversal, opposite letters or number values).', 2),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'blood-relations', 'Blood Relations', 'Draw a family tree with symbols: + for male, - for female, = for couples, vertical lines for generations.', 3),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'direction-sense', 'Direction Sense', 'Track each movement on a rough sketch.', 4),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'seating-arrangements', 'Seating Arrangements', 'Linear and circular arrangements.', 5),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'puzzles', 'Puzzles', 'Organise clues in a table (people × attributes).', 6),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'syllogisms', 'Syllogisms', 'Use Venn diagrams to test whether a conclusion is definitely true for every possible diagram.', 7),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'statement-and-conclusions', 'Statement and Conclusions / Assumptions', 'A conclusion must follow directly from the statement; an assumption is something the speaker takes for granted.', 8),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'analogies', 'Analogies', 'Identify the relationship in the first pair and apply it to the second.', 9),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'classification', 'Classification (Odd One Out)', 'Three items share a property; find the one that does not.', 10),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'order-and-ranking', 'Order and Ranking', 'Questions about positions in a row or ranks in a class.', 11),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'calendars', 'Calendars', 'Use odd days (remainder after dividing days by 7) to find days of the week.', 12),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'clocks', 'Clocks', 'The minute hand moves 6°/min and the hour hand 0.', 13),
((SELECT id FROM learning_modules WHERE slug = 'logical'), 'data-sufficiency', 'Data Sufficiency', 'Decide whether the given statements are enough to answer the question — you do not need the final value.', 14);
INSERT INTO lessons (topic_id, title, content, difficulty, est_minutes, sort_order) VALUES
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'number-series'), 'Number Series', '{"explanation":"Find the rule that generates the sequence, then apply it to find the next or the wrong term.","shortcuts":["Check differences first, then ratios","Look for squares/cubes (n², n³, n² ± 1)","Check differences of differences","Try alternate terms (two interleaved series)","Combined rules: ×2 + 1, ×3 - 2"],"solved_examples":[{"question":"2, 6, 12, 20, 30, ?","solution":"Differences 4, 6, 8, 10 → next 12 → 42 (n(n+1))."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'alphabet-series'), 'Alphabet Series', '{"explanation":"Letters follow position-based patterns. Convert letters to positions (A = 1 ... Z = 26).","shortcuts":["Remember EJOTY: E5, J10, O15, T20, Y25","Opposite letters sum to 27 (A-Z, B-Y)","Check forward/backward jumps and growing gaps"],"solved_examples":[{"question":"AZ, BY, CX, ?","solution":"First letters forward, second letters backward → DW."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'coding-and-decoding'), 'Coding and Decoding', '{"explanation":"A word is converted to a code using a hidden rule (letter shift, reversal, opposite letters or number values).","shortcuts":["Compare the first letter of the word and the code to find the shift","Check if the code is the reverse","Opposite letter: position 27 - n","Number codes often use positions or their sums"],"solved_examples":[{"question":"CAT → DBU; DOG → ?","solution":"+1 shift → EPH."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'blood-relations'), 'Blood Relations', '{"explanation":"Draw a family tree with symbols: + for male, - for female, = for couples, vertical lines for generations.","shortcuts":["Start from the end of a long statement (\"my grandfather''s only son\" = father)","Do not assume gender unless stated","Coded relations (A + B) → translate one symbol at a time"],"solved_examples":[{"question":"Pointing to a man, X says \"His mother is my mother''s only daughter.\"","solution":"Mother''s only daughter = X herself → the man is X''s son."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'direction-sense'), 'Direction Sense', '{"explanation":"Track each movement on a rough sketch. Right turn = 90° clockwise, left = 90° anticlockwise.","shortcuts":["Use a coordinate grid: North +y, East +x","Shortest distance = √(dx² + dy²)","At sunrise, shadows fall West; at sunset, East"],"solved_examples":[{"question":"Walk 3 km N, turn right 4 km. Distance?","solution":"√(9 + 16) = 5 km, towards North-East."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'seating-arrangements'), 'Seating Arrangements', '{"explanation":"Linear and circular arrangements. Place the most definite clue first, then fill in the rest.","shortcuts":["Facing the centre: left = clockwise, right = anticlockwise","Facing north in a row: your left is the viewer''s left","Fix one person in circular problems"],"solved_examples":[{"question":"A is opposite C; B on A''s right (square table). Who is on A''s left?","solution":"D."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'puzzles'), 'Puzzles', '{"explanation":"Organise clues in a table (people × attributes). Mark definite facts first, then eliminate.","shortcuts":["Start with clues that fix an exact position or pair","Use negative clues to eliminate","Check the final answer against every clue"],"solved_examples":[{"question":"A taller than B, shorter than C; D shorter than B. Shortest?","solution":"C > A > B > D → D."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'syllogisms'), 'Syllogisms', '{"explanation":"Use Venn diagrams to test whether a conclusion is definitely true for every possible diagram.","shortcuts":["All A are B → Some B are A (conversion)","No A is B → No B is A","\"Some\" + \"Some\" gives no definite conclusion","Complementary pair (some / no) → either-or"],"solved_examples":[{"question":"All A are B, all B are C. Then?","solution":"All A are C; some C are A."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'statement-and-conclusions'), 'Statement and Conclusions / Assumptions', '{"explanation":"A conclusion must follow directly from the statement; an assumption is something the speaker takes for granted.","shortcuts":["Reject extreme words: only, always, never, all (unless stated)","Do not use outside knowledge","Courses of action must be practical and solve the stated problem"],"solved_examples":[{"question":"\"Prices will rise next month.\" Conclusion: People may buy now.","solution":"Follows as a reasonable inference."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'analogies'), 'Analogies', '{"explanation":"Identify the relationship in the first pair and apply it to the second.","shortcuts":["Common relations: worker-tool, product-raw material, young one-adult, instrument-measurement","Number analogies: squares, cubes, ×k + c","Letter analogies: constant shifts"],"solved_examples":[{"question":"3 : 27 :: 4 : ?","solution":"Cube → 64."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'classification'), 'Classification (Odd One Out)', '{"explanation":"Three items share a property; find the one that does not.","shortcuts":["Check prime/composite, even/odd, squares, multiples","For words: category, function, origin","For letter pairs: gap between letters"],"solved_examples":[{"question":"17, 23, 27, 31","solution":"27 is not prime."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'order-and-ranking'), 'Order and Ranking', '{"explanation":"Questions about positions in a row or ranks in a class.","shortcuts":["Total = left + right - 1","Rank from bottom = total - rank from top + 1","People between = total - (pos1 + pos2) when they do not overlap"],"solved_examples":[{"question":"10th from left, 15th from right. Total?","solution":"24."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'calendars'), 'Calendars', '{"explanation":"Use odd days (remainder after dividing days by 7) to find days of the week.","shortcuts":["Ordinary year = 1 odd day, leap year = 2","100 years = 5 odd days, 200 = 3, 300 = 1, 400 = 0","Century years are leap only if divisible by 400","Month odd days: Jan 3, Feb 0/1, Mar 3, Apr 2 ..."],"solved_examples":[{"question":"1 Jan 2023 was Sunday. 1 Jan 2024?","solution":"2023 has 1 odd day → Monday."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'clocks'), 'Clocks', '{"explanation":"The minute hand moves 6°/min and the hour hand 0.5°/min, so the relative speed is 5.5°/min.","shortcuts":["Angle = |30H - 5.5M|","Hands coincide 11 times in 12 hours","Hands coincide at 60H/11 minutes past H","Right angle 22 times in 12 hours"],"solved_examples":[{"question":"Angle at 3:40?","solution":"|90 - 220| = 130°."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'logical' AND t.slug = 'data-sufficiency'), 'Data Sufficiency', '{"explanation":"Decide whether the given statements are enough to answer the question — you do not need the final value.","shortcuts":["Check each statement alone first, then together","For yes/no questions, a definite \"no\" is also sufficient","Count unknowns vs independent equations"],"solved_examples":[{"question":"x? I: x + y = 5. II: x - y = 1.","solution":"Both together needed → x = 3."}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 20, 0);
INSERT INTO learning_topics (module_id, slug, title, summary, sort_order) VALUES
((SELECT id FROM learning_modules WHERE slug = 'verbal'), 'reading-comprehension', 'Reading Comprehension', 'Read the questions first, then the passage actively, noting the main idea, tone and key facts.', 0),
((SELECT id FROM learning_modules WHERE slug = 'verbal'), 'synonyms', 'Synonyms', 'A synonym is a word with the same or nearly the same meaning.', 1),
((SELECT id FROM learning_modules WHERE slug = 'verbal'), 'antonyms', 'Antonyms', 'An antonym is a word with the opposite meaning.', 2),
((SELECT id FROM learning_modules WHERE slug = 'verbal'), 'grammar', 'Grammar Essentials', 'Most placement grammar questions test subject-verb agreement, tenses, articles, prepositions and conjunction pairs.', 3),
((SELECT id FROM learning_modules WHERE slug = 'verbal'), 'sentence-correction', 'Sentence Correction', 'Pick the version that is grammatically correct, clear and concise.', 4),
((SELECT id FROM learning_modules WHERE slug = 'verbal'), 'error-detection', 'Error Detection', 'Identify which part of a sentence contains a grammatical error.', 5),
((SELECT id FROM learning_modules WHERE slug = 'verbal'), 'fill-in-the-blanks', 'Fill in the Blanks', 'Choose the word that fits grammatically and in meaning.', 6),
((SELECT id FROM learning_modules WHERE slug = 'verbal'), 'para-jumbles', 'Para Jumbles', 'Arrange sentences into a logical paragraph.', 7),
((SELECT id FROM learning_modules WHERE slug = 'verbal'), 'sentence-completion', 'Sentence Completion', 'Complete sentences using correct structures and logical meaning.', 8),
((SELECT id FROM learning_modules WHERE slug = 'verbal'), 'vocabulary', 'Vocabulary Building', 'A strong vocabulary helps in reading, writing and interviews.', 9),
((SELECT id FROM learning_modules WHERE slug = 'verbal'), 'active-and-passive-voice', 'Active and Passive Voice', 'In passive voice, the object becomes the subject and the verb becomes "be + past participle".', 10),
((SELECT id FROM learning_modules WHERE slug = 'verbal'), 'direct-and-indirect-speech', 'Direct and Indirect Speech', 'Reported speech changes pronouns, tenses and time words.', 11);
INSERT INTO lessons (topic_id, title, content, difficulty, est_minutes, sort_order) VALUES
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'verbal' AND t.slug = 'reading-comprehension'), 'Reading Comprehension', '{"explanation":"Read the questions first, then the passage actively, noting the main idea, tone and key facts.","shortcuts":["Answer only from the passage, not outside knowledge","Main idea questions → first and last sentences","Vocabulary-in-context: substitute each option into the sentence","Tone words: balanced, critical, optimistic, neutral"],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'verbal' AND t.slug = 'synonyms'), 'Synonyms', '{"explanation":"A synonym is a word with the same or nearly the same meaning.","shortcuts":["Use the word in a sentence and substitute options","Learn words in groups (e.g. happy: elated, jubilant)","Watch for antonym traps among the options"],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'verbal' AND t.slug = 'antonyms'), 'Antonyms', '{"explanation":"An antonym is a word with the opposite meaning.","shortcuts":["First find the exact meaning, then its opposite","Prefixes like un-, in-, dis-, mal- often form antonyms","Eliminate synonyms placed as traps"],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'verbal' AND t.slug = 'grammar'), 'Grammar Essentials', '{"explanation":"Most placement grammar questions test subject-verb agreement, tenses, articles, prepositions and conjunction pairs.","shortcuts":["Each/every/either/neither → singular verb","Since + point in time; for + duration","Hardly/scarcely ... when; no sooner ... than","An before vowel sounds (an hour, a university)"],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'verbal' AND t.slug = 'sentence-correction'), 'Sentence Correction', '{"explanation":"Pick the version that is grammatically correct, clear and concise.","shortcuts":["Check agreement, tense and pronouns first","Remove redundancy (revert back, return back)","Uncountable nouns: advice, information, equipment"],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'verbal' AND t.slug = 'error-detection'), 'Error Detection', '{"explanation":"Identify which part of a sentence contains a grammatical error.","shortcuts":["Read the whole sentence before judging a part","Common errors: agreement, prepositions, comparatives, pronoun case","\"No error\" is a valid option — do not force an error"],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'verbal' AND t.slug = 'fill-in-the-blanks'), 'Fill in the Blanks', '{"explanation":"Choose the word that fits grammatically and in meaning.","shortcuts":["Use grammar to eliminate options first","Look for clue words (although, because, despite)","Watch confusable words: affect/effect, amiable/amicable, assess/access"],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'verbal' AND t.slug = 'para-jumbles'), 'Para Jumbles', '{"explanation":"Arrange sentences into a logical paragraph.","shortcuts":["Find the opening sentence (introduces the topic, no pronoun reference)","Find mandatory pairs (a pronoun and its noun, \"however\" and its contrast)","Look for time order and cause-effect"],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'verbal' AND t.slug = 'sentence-completion'), 'Sentence Completion', '{"explanation":"Complete sentences using correct structures and logical meaning.","shortcuts":["Conjunction pairs: not only...but also, either...or","Conditionals: if + past perfect → would have + pp","\"Although\" never with \"but\""],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'verbal' AND t.slug = 'vocabulary'), 'Vocabulary Building', '{"explanation":"A strong vocabulary helps in reading, writing and interviews.","shortcuts":["Learn 10 words a day with meaning and an example sentence","Use roots: bene = good, mal = bad, chron = time","Revise using spaced repetition"],"word_list":[{"word":"Abundant","meaning":"existing in large quantities","synonym":"Plentiful","antonym":"Scarce"},{"word":"Benevolent","meaning":"kind and generous","synonym":"Charitable","antonym":"Malevolent"},{"word":"Candid","meaning":"truthful and straightforward","synonym":"Frank","antonym":"Evasive"},{"word":"Diligent","meaning":"showing care and effort in work","synonym":"Hardworking","antonym":"Lazy"},{"word":"Eloquent","meaning":"fluent and persuasive in speaking","synonym":"Articulate","antonym":"Inarticulate"},{"word":"Frugal","meaning":"careful with money","synonym":"Thrifty","antonym":"Extravagant"},{"word":"Gregarious","meaning":"fond of company; sociable","synonym":"Sociable","antonym":"Reclusive"},{"word":"Hostile","meaning":"unfriendly; antagonistic","synonym":"Aggressive","antonym":"Friendly"},{"word":"Immense","meaning":"extremely large","synonym":"Enormous","antonym":"Tiny"},{"word":"Jubilant","meaning":"feeling great joy","synonym":"Elated","antonym":"Dejected"},{"word":"Lucid","meaning":"clearly expressed; easy to understand","synonym":"Clear","antonym":"Obscure"},{"word":"Meticulous","meaning":"showing great attention to detail","synonym":"Thorough","antonym":"Careless"},{"word":"Novice","meaning":"a person new to an activity","synonym":"Beginner","antonym":"Expert"},{"word":"Obsolete","meaning":"no longer in use","synonym":"Outdated","antonym":"Modern"},{"word":"Pragmatic","meaning":"dealing with things practically","synonym":"Practical","antonym":"Idealistic"},{"word":"Prudent","meaning":"acting with care for the future","synonym":"Wise","antonym":"Reckless"},{"word":"Resilient","meaning":"able to recover quickly from difficulty","synonym":"Tough","antonym":"Fragile"},{"word":"Scrutinize","meaning":"examine closely","synonym":"Inspect","antonym":"Overlook"},{"word":"Tenacious","meaning":"holding firmly to a purpose","synonym":"Persistent","antonym":"Irresolute"},{"word":"Ubiquitous","meaning":"present everywhere","synonym":"Omnipresent","antonym":"Rare"},{"word":"Vivid","meaning":"producing strong, clear images","synonym":"Bright","antonym":"Dull"},{"word":"Zealous","meaning":"full of energy and enthusiasm","synonym":"Eager","antonym":"Apathetic"},{"word":"Ambiguous","meaning":"open to more than one interpretation","synonym":"Unclear","antonym":"Explicit"},{"word":"Brevity","meaning":"concise use of words","synonym":"Conciseness","antonym":"Verbosity"},{"word":"Cordial","meaning":"warm and friendly","synonym":"Amiable","antonym":"Unfriendly"},{"word":"Deter","meaning":"discourage from acting","synonym":"Discourage","antonym":"Encourage"},{"word":"Enhance","meaning":"improve the quality of","synonym":"Improve","antonym":"Diminish"},{"word":"Feasible","meaning":"possible and practical to do","synonym":"Viable","antonym":"Impossible"},{"word":"Genuine","meaning":"truly what it is said to be","synonym":"Authentic","antonym":"Fake"},{"word":"Hinder","meaning":"create difficulties for","synonym":"Obstruct","antonym":"Facilitate"}],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'verbal' AND t.slug = 'active-and-passive-voice'), 'Active and Passive Voice', '{"explanation":"In passive voice, the object becomes the subject and the verb becomes \"be + past participle\".","shortcuts":["Simple present: is/are + pp","Simple past: was/were + pp","Continuous: is being / was being + pp","Perfect: has/have/had been + pp","Future: will be + pp"],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'verbal' AND t.slug = 'direct-and-indirect-speech'), 'Direct and Indirect Speech', '{"explanation":"Reported speech changes pronouns, tenses and time words.","shortcuts":["Present → past, past → past perfect, will → would, can → could","Universal truths keep the present tense","Today → that day, tomorrow → the next day, yesterday → the previous day, this → that","Questions: asked + if/wh-word + statement order"],"practice_note":"Practise with timed quizzes below."}'::jsonb, 'easy', 15, 0);
