INSERT INTO lessons (topic_id, title, content, difficulty, est_minutes, sort_order) VALUES
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'english-grammar'), 'English Grammar for Professionals', '{"explanation":"Clear grammar builds credibility in emails, interviews and reports. Focus on subject-verb agreement, correct tenses, articles and prepositions — these cause most mistakes in Indian English.","tips":["Use simple present for facts, present perfect for experience (\"I have built\")","Avoid \"myself Rahul\" — say \"I am Rahul\"","\"Discuss\" does not take \"about\"; \"revert\" means \"reply\" (avoid \"revert back\")"],"example":"✗ \"I am having 2 years experience.\"\n✓ \"I have two years of experience.\"","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'vocabulary'), 'Vocabulary Building', '{"explanation":"A precise vocabulary lets you express ideas confidently. Learn words in context, use them in sentences and revise regularly. Prefer simple, precise words over complex ones.","tips":["Learn 5-10 words a day with an example sentence","Group words by theme (work, emotions, technology)","Replace vague words: \"good\" → effective, reliable, efficient"],"example":"Instead of \"The project was very good\", say \"The project reduced report generation time by 40%.\"","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'pronunciation'), 'Pronunciation', '{"explanation":"Clear pronunciation matters more than accent. Speak at a moderate pace, stress the right syllables and pronounce word endings clearly.","tips":["Stress: DEvelop vs deVElop → \"deVELop\"; \"comPUter\"","Do not drop final consonants (asked = \"askt\")","Record yourself and compare with a dictionary audio"],"example":"Commonly mispronounced: \"determine\" (de-TER-min), \"suite\" (sweet), \"often\" (OF-en).","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'fluency'), 'Fluency', '{"explanation":"Fluency means speaking smoothly without long pauses or fillers. It comes from practice, structured thinking and acceptance of small mistakes.","tips":["Think in short sentences","Replace \"umm\" with a brief silent pause","Practise 2-minute talks on random topics daily"],"example":"Use the PREP structure: Point → Reason → Example → Point.","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'listening'), 'Listening Skills', '{"explanation":"Good listening helps you understand questions correctly and respond relevantly — a major factor in interviews and group discussions.","tips":["Do not interrupt; wait for the full question","Paraphrase to confirm: \"So you are asking about ...\"","Note keywords while listening to long questions"],"example":"Interviewer: \"Tell me about a challenge in your project.\" Listen for the key word \"challenge\" — answer about a problem and how you solved it, not the whole project.","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'speaking'), 'Speaking with Clarity', '{"explanation":"Effective speaking is structured, concise and audience-focused. Start with the main point, then support it.","tips":["Lead with your conclusion","Use numbers and examples","Keep answers 60-120 seconds unless asked for more"],"example":"\"I prefer Java for backend work for two reasons: its strong typing catches errors early, and Spring Boot speeds up REST API development — I used it in my placement-portal project.\"","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'professional-communication'), 'Professional Communication', '{"explanation":"Professional communication is polite, clear and purposeful, whether on email, chat or calls. It respects the reader''s time.","tips":["State the purpose in the first line","Use bullet points for multiple items","Close with a clear next step","Avoid slang and excessive exclamation marks"],"example":"Chat message: \"Hi Priya, could you review PR #42 by 4 pm today? It fixes the login timeout bug. Thanks!\"","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'email-writing'), 'Email Writing', '{"explanation":"A professional email has a clear subject line, greeting, concise body, polite closing and signature. Proofread before sending.","tips":["Subject: specific (e.g. \"Application for Software Engineer Intern - Asha Rao\")","Greeting: \"Dear Ms. Sharma,\" or \"Hello Team,\"","Body: purpose → details → request","Closing: \"Regards,\" + name, phone, LinkedIn"],"example":"Subject: Request for Interview Reschedule - Asha Rao\n\nDear Ms. Sharma,\n\nThank you for shortlisting me for the Software Engineer role. I have a university exam on 12 March, which clashes with my interview slot. Could we reschedule to 13 or 14 March at any time convenient for you?\n\nI apologise for the inconvenience.\n\nRegards,\nAsha Rao\n+91 98765 43210","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'group-discussions'), 'Group Discussions', '{"explanation":"Group discussions test communication, reasoning, teamwork and leadership. Quality and relevance matter more than how long you speak.","tips":["Start or summarise if you can — both are high-visibility","Support points with facts or examples","Acknowledge others: \"Building on Rahul''s point ...\"","Never shout or interrupt aggressively","Bring the group back to the topic if it drifts"],"example":"Topic: \"Should AI replace teachers?\"\nOpening: \"AI can personalise learning at scale, but teaching also involves mentoring and motivation. I believe AI should assist teachers rather than replace them.\"","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'presentation-skills'), 'Presentation Skills', '{"explanation":"Good presentations have a clear story, simple slides and a confident delivery. Know your audience and your one key message.","tips":["Rule of three: three main points","One idea per slide, few words, large fonts","Practise with a timer","Make eye contact and pause after key points"],"example":"Project demo structure: Problem (30 s) → Solution & demo (2 min) → Tech stack & architecture (1 min) → Results & learnings (30 s).","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'confidence'), 'Building Confidence', '{"explanation":"Confidence comes from preparation and practice, not from knowing everything. It shows in posture, voice and willingness to say \"I don''t know, but here is how I would find out.\"","tips":["Prepare stories for common questions","Practise mock interviews","Use power posture and steady breathing before interviews","Reframe nervousness as excitement"],"example":"\"I haven''t used Kubernetes in a project yet, but I understand it orchestrates containers. I have used Docker, and I''m learning Kubernetes through the official tutorials.\"","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'body-language'), 'Body Language', '{"explanation":"Non-verbal signals strongly affect first impressions. Open, calm body language signals confidence and honesty.","tips":["Sit upright, slightly leaning forward","Keep hands visible and relaxed; avoid fidgeting","Nod to show you are listening","Smile naturally at the start and end"],"example":"In video interviews: camera at eye level, face well lit, look at the camera when speaking.","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'eye-contact'), 'Eye Contact', '{"explanation":"Appropriate eye contact shows attention and confidence. Too little seems evasive; staring feels uncomfortable.","tips":["Hold eye contact for 3-5 seconds, then glance away naturally","In panels, address the questioner but include others","On video, look at the camera, not the screen"],"example":"Panel tip: start your answer looking at the person who asked, then include other panel members, and finish with the questioner.","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'active-listening'), 'Active Listening', '{"explanation":"Active listening means fully concentrating, understanding and responding thoughtfully. It builds rapport and prevents misunderstandings.","tips":["Paraphrase: \"If I understand correctly, ...\"","Ask clarifying questions","Do not plan your reply while the other person is still talking"],"example":"\"So the main issue is that the API is slow during peak hours — is the delay in the database or in the network?\"","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'leadership'), 'Leadership', '{"explanation":"Leadership is the ability to guide a group towards a goal — through initiative, ownership and supporting others, not just through titles.","tips":["Use STAR stories showing initiative","Show how you helped others succeed","Mention decisions and their results"],"example":"\"In our hackathon team, tasks were unclear. I split the work into four modules, set up a shared board, and held 10-minute check-ins. We finished a working demo and placed second.\"","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'teamwork'), 'Teamwork', '{"explanation":"Teamwork is collaborating effectively, communicating openly, and putting team goals first. Recruiters look for how you handle disagreements and contribute.","tips":["Describe your specific role in team projects","Show how you resolved a conflict respectfully","Credit others"],"example":"\"When two teammates disagreed on using MySQL vs MongoDB, I suggested listing our data needs. Since our data was relational, we chose MySQL — and both agreed because the decision was based on requirements.\"","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'time-management'), 'Time Management', '{"explanation":"Time management helps balance academics, placement preparation and projects. Plan, prioritise and protect focused time.","tips":["Use a weekly plan and a daily top-3 list","Eisenhower matrix: urgent vs important","Pomodoro: 25 min focus + 5 min break","Track study time with the BrainBridge Daily Tracker"],"example":"Daily plan: 1 hr DSA, 30 min aptitude, 30 min project, 15 min communication practice.","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'communication' AND t.slug = 'stress-management'), 'Stress Management', '{"explanation":"Placement season is stressful. Managing stress keeps your performance steady and protects your health.","tips":["Sleep 7-8 hours, especially before tests","Break preparation into small daily goals","Exercise or walk daily","Talk to friends, mentors or a counsellor when overwhelmed","Treat rejections as feedback, not verdicts"],"example":"After a rejection: note 2 questions you struggled with, add them to your plan, and practise them before the next interview.","practice":["Complete a related communication exercise below and review the rubric feedback."]}'::jsonb, 'easy', 15, 0);
INSERT INTO learning_topics (module_id, slug, title, summary, sort_order) VALUES
((SELECT id FROM learning_modules WHERE slug = 'interview'), 'body-language', 'Body Language in Interviews', 'Sit upright, lean slightly forward, keep hands relaxed and visible, and avoid crossing arms or fidgeting.', 0),
((SELECT id FROM learning_modules WHERE slug = 'interview'), 'eye-contact', 'Eye Contact', 'Hold natural eye contact while speaking and listening; in panels, address the questioner first and include others.', 1),
((SELECT id FROM learning_modules WHERE slug = 'interview'), 'sitting-posture', 'Sitting Posture', 'Wait to be offered a seat, sit with your back straight and feet flat, keep your bag on the floor, and avoid leaning back or slouching..', 2),
((SELECT id FROM learning_modules WHERE slug = 'interview'), 'professional-dressing', 'Professional Dressing', 'Choose clean, ironed formal or smart-casual clothes, neat grooming, minimal accessories and comfortable formal shoes.', 3),
((SELECT id FROM learning_modules WHERE slug = 'interview'), 'speaking-confidently', 'Speaking Confidently', 'Speak at a moderate pace, pause instead of using fillers, lead with your main point and support it with an example.', 4),
((SELECT id FROM learning_modules WHERE slug = 'interview'), 'handling-unknown-questions', 'Handling Unknown Questions', 'Stay calm, admit what you do not know, connect to related knowledge, reason aloud about how you would approach it, and stay positive..', 5),
((SELECT id FROM learning_modules WHERE slug = 'interview'), 'asking-questions', 'Asking Questions', 'Prepare 2-3 questions about the role, team, success expectations and learning opportunities.', 6);
INSERT INTO lessons (topic_id, title, content, difficulty, est_minutes, sort_order) VALUES
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'interview' AND t.slug = 'body-language'), 'Body Language in Interviews', '{"explanation":"Sit upright, lean slightly forward, keep hands relaxed and visible, and avoid crossing arms or fidgeting. Mirror the interviewer''s energy politely.","tips":["Sit upright, lean slightly forward, keep hands relaxed and visible, and avoid crossing arms or fidgeting","Mirror the interviewer''s energy politely"]}'::jsonb, 'easy', 10, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'interview' AND t.slug = 'eye-contact'), 'Eye Contact', '{"explanation":"Hold natural eye contact while speaking and listening; in panels, address the questioner first and include others. On video, look at the camera.","tips":["Hold natural eye contact while speaking and listening; in panels, address the questioner first and include others","On video, look at the camera"]}'::jsonb, 'easy', 10, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'interview' AND t.slug = 'sitting-posture'), 'Sitting Posture', '{"explanation":"Wait to be offered a seat, sit with your back straight and feet flat, keep your bag on the floor, and avoid leaning back or slouching.","tips":["Wait to be offered a seat, sit with your back straight and feet flat, keep your bag on the floor, and avoid leaning back or slouching"]}'::jsonb, 'easy', 10, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'interview' AND t.slug = 'professional-dressing'), 'Professional Dressing', '{"explanation":"Choose clean, ironed formal or smart-casual clothes, neat grooming, minimal accessories and comfortable formal shoes. For video calls, dress fully and use a plain background.","tips":["Choose clean, ironed formal or smart-casual clothes, neat grooming, minimal accessories and comfortable formal shoes","For video calls, dress fully and use a plain background"]}'::jsonb, 'easy', 10, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'interview' AND t.slug = 'speaking-confidently'), 'Speaking Confidently', '{"explanation":"Speak at a moderate pace, pause instead of using fillers, lead with your main point and support it with an example. Practise answers aloud.","tips":["Speak at a moderate pace, pause instead of using fillers, lead with your main point and support it with an example","Practise answers aloud"]}'::jsonb, 'easy', 10, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'interview' AND t.slug = 'handling-unknown-questions'), 'Handling Unknown Questions', '{"explanation":"Stay calm, admit what you do not know, connect to related knowledge, reason aloud about how you would approach it, and stay positive.","tips":["Stay calm, admit what you do not know, connect to related knowledge, reason aloud about how you would approach it, and stay positive"]}'::jsonb, 'easy', 10, 0),
((SELECT t.id FROM learning_topics t JOIN learning_modules m ON m.id = t.module_id WHERE m.slug = 'interview' AND t.slug = 'asking-questions'), 'Asking Questions', '{"explanation":"Prepare 2-3 questions about the role, team, success expectations and learning opportunities. Avoid questions you could answer from the company website.","tips":["Prepare 2-3 questions about the role, team, success expectations and learning opportunities","Avoid questions you could answer from the company website"]}'::jsonb, 'easy', 10, 0);
INSERT INTO aptitude_questions (section, topic_slug, question, options, answer_index, explanation, difficulty) VALUES
('quant', 'number-systems', 'How many numbers from 1 to 425 are divisible by 9?', '["37","57","47","52"]'::jsonb, 2, 'Count = floor(425 / 9) = 47.', 'easy'),
('quant', 'number-systems', 'What is the unit digit of 78 × 40?', '["3","0","8","1"]'::jsonb, 1, 'Only unit digits matter: 8 × 0 = 0, so the unit digit is 0.', 'easy'),
