('quant', 'percentages', 'What is 45% of 660?', '["594","267","297","148.5"]'::jsonb, 2, '45% of 660 = 45/100 × 660 = 297.', 'easy'),
('quant', 'percentages', 'What percent of 40 is 4?', '["15%","10%","5%","20%"]'::jsonb, 1, '(4/40) × 100 = 10%.', 'easy'),
('quant', 'percentages', 'A number 1250 is increased by 10%. What is the new number?', '["1237","1513","1651","1375"]'::jsonb, 3, '1250 × (1 + 10/100) = 1375.', 'easy'),
('quant', 'percentages', 'What is 60% of 620?', '["446","372","744","409"]'::jsonb, 1, '60% of 620 = 60/100 × 620 = 372.', 'easy'),
('quant', 'percentages', 'A salary is increased by 25% and then by 25%. What is the overall percentage increase?', '["56.25%","50%","54.75%","62.5%"]'::jsonb, 0, 'Net change = a + b + ab/100 = 25 + 25 + 6.25 = 56.25%.', 'medium'),
('quant', 'percentages', 'A price is first increased by 40% and then decreased by 40%. What is the net change?', '["No change","16% decrease","32% decrease","40% decrease"]'::jsonb, 1, 'Net = p - p - p²/100 = -16%, i.e. a 16% decrease.', 'medium'),
('quant', 'percentages', 'The price of sugar rises by 25%. By what percent must a family reduce consumption to keep expenditure unchanged?', '["23%","12.5%","25%","20%"]'::jsonb, 3, 'Reduction = p/(100+p) × 100 = 25/125 × 100 = 20%.', 'medium'),
('quant', 'percentages', 'A salary is increased by 30% and then by 10%. What is the overall percentage increase?', '["43%","30%","40%","41.5%"]'::jsonb, 0, 'Net change = a + b + ab/100 = 30 + 10 + 3 = 43%.', 'medium'),
('quant', 'percentages', 'A price is first increased by 10% and then decreased by 10%. What is the net change?', '["No change","1% decrease","10% decrease","1% increase"]'::jsonb, 1, 'Net = p - p - p²/100 = -1%, i.e. a 1% decrease.', 'medium'),
('quant', 'percentages', 'A salary is increased by 40% and then by 5%. What is the overall percentage increase?', '["45%","47%","20%","45.5%"]'::jsonb, 1, 'Net change = a + b + ab/100 = 40 + 5 + 2 = 47%.', 'medium'),
('quant', 'percentages', 'A price is first increased by 30% and then decreased by 30%. What is the net change?', '["9% increase","9% decrease","30% decrease","18% decrease"]'::jsonb, 1, 'Net = p - p - p²/100 = -9%, i.e. a 9% decrease.', 'medium'),
('quant', 'percentages', 'The price of sugar rises by 60%. By what percent must a family reduce consumption to keep expenditure unchanged?', '["60%","30%","40.5%","37.5%"]'::jsonb, 3, 'Reduction = p/(100+p) × 100 = 60/160 × 100 = 37.5%.', 'medium'),
('quant', 'percentages', 'A price is first increased by 20% and then decreased by 20%. What is the net change?', '["20% decrease","4% decrease","4% increase","8% decrease"]'::jsonb, 1, 'Net = p - p - p²/100 = -4%, i.e. a 4% decrease.', 'medium'),
('quant', 'percentages', 'The price of sugar rises by 50%. By what percent must a family reduce consumption to keep expenditure unchanged?', '["36.33%","33.33%","25%","31.33%"]'::jsonb, 1, 'Reduction = p/(100+p) × 100 = 50/150 × 100 = 33.33%.', 'medium'),
('quant', 'percentages', 'A salary is increased by 40% and then by 10%. What is the overall percentage increase?', '["54%","52.5%","40%","56%"]'::jsonb, 0, 'Net change = a + b + ab/100 = 40 + 10 + 4 = 54%.', 'medium'),
('quant', 'percentages', 'The price of sugar rises by 100%. By what percent must a family reduce consumption to keep expenditure unchanged?', '["100%","50%","53%","48%"]'::jsonb, 1, 'Reduction = p/(100+p) × 100 = 100/200 × 100 = 50%.', 'medium'),
('quant', 'percentages', 'A salary is increased by 20% and then by 15%. What is the overall percentage increase?', '["38%","36.5%","35%","40%"]'::jsonb, 0, 'Net change = a + b + ab/100 = 20 + 15 + 3 = 38%.', 'medium'),
('quant', 'percentages', 'The price of sugar rises by 20%. By what percent must a family reduce consumption to keep expenditure unchanged?', '["16.67%","14.67%","19.67%","20%"]'::jsonb, 0, 'Reduction = p/(100+p) × 100 = 20/120 × 100 = 16.67%.', 'medium'),
('quant', 'percentages', 'A salary is increased by 30% and then by 5%. What is the overall percentage increase?', '["36.5%","35%","15%","38.5%"]'::jsonb, 0, 'Net change = a + b + ab/100 = 30 + 5 + 1.5 = 36.5%.', 'medium'),
('quant', 'percentages', 'A salary is increased by 10% and then by 10%. What is the overall percentage increase?', '["20%","19.5%","23%","21%"]'::jsonb, 3, 'Net change = a + b + ab/100 = 10 + 10 + 1 = 21%.', 'medium'),
('quant', 'percentages', 'A salary is increased by 40% and then by 15%. What is the overall percentage increase?', '["61%","63%","60%","59.5%"]'::jsonb, 0, 'Net change = a + b + ab/100 = 40 + 15 + 6 = 61%.', 'medium'),
('quant', 'percentages', 'A salary is increased by 30% and then by 15%. What is the overall percentage increase?', '["45%","51.5%","49.5%","48%"]'::jsonb, 2, 'Net change = a + b + ab/100 = 30 + 15 + 4.5 = 49.5%.', 'medium'),
('quant', 'percentages', 'The population of a town is 15000. It grows by 10% every year. What will it be after 2 years?', '["9075","14520","18150","21780"]'::jsonb, 2, '15000 × (1 + 10/100)² = 18150.', 'hard'),
('quant', 'percentages', 'If A''s income is 20% less than B''s, by what percent is B''s income more than A''s?', '["29%","16.67%","25%","22%"]'::jsonb, 2, 'B more than A = p/(100 - p) × 100 = 20/80 × 100 = 25%.', 'hard'),
