('quant', 'percentages', 'The population of a town is 14000. It grows by 5% every year. What will it be after 2 years?', '["12347","13891","15435","18523"]'::jsonb, 2, '14000 × (1 + 5/100)² = 15435.', 'hard'),
('quant', 'percentages', 'The population of a town is 6000. It grows by 20% every year. What will it be after 2 years?', '["8640","10368","6912","4320"]'::jsonb, 0, '6000 × (1 + 20/100)² = 8640.', 'hard'),
('quant', 'percentages', 'A student needs 40% to pass. He scores 135 marks and fails by 23 marks. What are the maximum marks?', '["435","197.5","395","475"]'::jsonb, 2, 'Pass marks = 135 + 23 = 158 = 40% of maximum. Maximum = 158 × 100/40 = 395.', 'hard'),
('quant', 'percentages', 'The population of a town is 6000. It grows by 10% every year. What will it be after 2 years?', '["7986","3630","7260","5808"]'::jsonb, 2, '6000 × (1 + 10/100)² = 7260.', 'hard'),
('quant', 'profit-and-loss', 'A shopkeeper buys an item for ₹700 and sells it at a loss of 10%. What is the selling price?', '["₹567","₹770","₹693","₹630"]'::jsonb, 3, 'SP = CP × (1 - 10/100) = ₹630.', 'easy'),
('quant', 'profit-and-loss', 'The marked price of a shirt is ₹4400 and a discount of 20% is offered. What is the selling price?', '["₹1760","₹3520","₹3872","₹2816"]'::jsonb, 1, 'SP = MP × (1 - 20/100) = ₹3520.', 'easy'),
('quant', 'profit-and-loss', 'An article bought for ₹1300 is sold for ₹1560. What is the profit percentage?', '["20%","40%","25%","17%"]'::jsonb, 0, 'Profit = ₹260. Profit% = 260/1300 × 100 = 20%.', 'easy'),
('quant', 'profit-and-loss', 'A shopkeeper buys an item for ₹1250 and sells it at a loss of 15%. What is the selling price?', '["₹2125","₹531.25","₹1168.5","₹1062.5"]'::jsonb, 3, 'SP = CP × (1 - 15/100) = ₹1062.5.', 'easy'),
('quant', 'profit-and-loss', 'The marked price of a shirt is ₹3300 and a discount of 10% is offered. What is the selling price?', '["₹2970","₹2376","₹5940","₹2673"]'::jsonb, 0, 'SP = MP × (1 - 10/100) = ₹2970.', 'easy'),
('quant', 'profit-and-loss', 'An article bought for ₹3000 is sold for ₹3450. What is the profit percentage?', '["20%","13%","15%","30%"]'::jsonb, 2, 'Profit = ₹450. Profit% = 449.99999999999955/3000 × 100 = 15%.', 'easy'),
('quant', 'profit-and-loss', 'A shopkeeper buys an item for ₹2100 and sells it at a loss of 10%. What is the selling price?', '["₹1701","₹2310","₹1890","₹2268"]'::jsonb, 2, 'SP = CP × (1 - 10/100) = ₹1890.', 'easy'),
('quant', 'profit-and-loss', 'The marked price of a shirt is ₹4100 and a discount of 20% is offered. What is the selling price?', '["₹1640","₹3280","₹3608","₹6560"]'::jsonb, 1, 'SP = MP × (1 - 20/100) = ₹3280.', 'easy'),
('quant', 'profit-and-loss', 'An article bought for ₹1250 is sold for ₹1312.5. What is the profit percentage?', '["10%","5%","3%","None of these 1"]'::jsonb, 1, 'Profit = ₹62.5. Profit% = 62.5/1250 × 100 = 5%.', 'easy'),
('quant', 'profit-and-loss', 'A shopkeeper buys an item for ₹400 and sells it at a loss of 25%. What is the selling price?', '["₹360","₹300","₹150","₹270"]'::jsonb, 1, 'SP = CP × (1 - 25/100) = ₹300.', 'easy'),
('quant', 'profit-and-loss', 'The marked price of a shirt is ₹2400 and a discount of 20% is offered. What is the selling price?', '["₹960","₹1536","₹1728","₹1920"]'::jsonb, 3, 'SP = MP × (1 - 20/100) = ₹1920.', 'easy'),
('quant', 'profit-and-loss', 'An article bought for ₹2350 is sold for ₹2632. What is the profit percentage?', '["11%","12%","10%","17%"]'::jsonb, 1, 'Profit = ₹282. Profit% = 282.00000000000045/2350 × 100 = 12%.', 'easy'),
('quant', 'profit-and-loss', 'A shopkeeper buys an item for ₹350 and sells it at a loss of 25%. What is the selling price?', '["₹288.5","₹262.5","₹236.5","₹131.25"]'::jsonb, 1, 'SP = CP × (1 - 25/100) = ₹262.5.', 'easy'),
('quant', 'profit-and-loss', 'The marked price of a shirt is ₹3800 and a discount of 15% is offered. What is the selling price?', '["₹2584","₹3876","₹3230","₹1615"]'::jsonb, 2, 'SP = MP × (1 - 15/100) = ₹3230.', 'easy'),
('quant', 'profit-and-loss', 'An article bought for ₹2200 is sold for ₹2420. What is the profit percentage?', '["20%","15%","10%","9%"]'::jsonb, 2, 'Profit = ₹220. Profit% = 220/2200 × 100 = 10%.', 'easy'),
('quant', 'profit-and-loss', 'A shopkeeper buys an item for ₹650 and sells it at a loss of 5%. What is the selling price?', '["₹617.5","₹555.5","₹1235","₹741.5"]'::jsonb, 0, 'SP = CP × (1 - 5/100) = ₹617.5.', 'easy'),
('quant', 'profit-and-loss', 'The marked price of a shirt is ₹400 and a discount of 30% is offered. What is the selling price?', '["₹280","₹252","₹336","₹140"]'::jsonb, 0, 'SP = MP × (1 - 30/100) = ₹280.', 'easy'),
('quant', 'profit-and-loss', 'An article bought for ₹1050 is sold for ₹1102.5. What is the profit percentage?', '["5%","3%","None of these 1","10%"]'::jsonb, 0, 'Profit = ₹52.5. Profit% = 52.5/1050 × 100 = 5%.', 'easy'),
('quant', 'profit-and-loss', 'A trader marks goods 20% above cost price and allows a discount of 10%. What is his profit or loss percentage?', '["9% loss","10% loss","10% profit","8% profit"]'::jsonb, 3, 'Take CP = 100. MP = 120, SP = 120 × 0.9 = 108. Profit = 8%.', 'medium'),
('quant', 'profit-and-loss', 'If the cost price of 25 articles equals the selling price of 20 articles, find the profit percentage.', '["30%","25%","20%","50%"]'::jsonb, 1, 'CP of 25 = SP of 20. Gain/loss on 20 articles = 5 articles'' CP. % = 5/20 × 100 = 25%.', 'medium'),
('quant', 'profit-and-loss', 'A watch is sold at a loss of 10%. Had it been sold for ₹416 more, there would have been a gain of 6%. Find the cost price.', '["₹3120","₹2340","₹2600","₹1300"]'::jsonb, 2, 'Difference of 16% of CP = ₹416, so CP = 416 × 100/16 = ₹2600.', 'medium'),
('quant', 'profit-and-loss', 'A trader marks goods 40% above cost price and allows a discount of 25%. What is his profit or loss percentage?', '["15% profit","6% loss","5% profit","25% loss"]'::jsonb, 2, 'Take CP = 100. MP = 140, SP = 140 × 0.75 = 105. Profit = 5%.', 'medium'),
('quant', 'profit-and-loss', 'If the cost price of 15 articles equals the selling price of 16 articles, find the loss percentage.', '["1%","12.5%","11.25%","6.25%"]'::jsonb, 3, 'CP of 15 = SP of 16. Gain/loss on 16 articles = 1 articles'' CP. % = 1/16 × 100 = 6.25%.', 'medium'),
('quant', 'profit-and-loss', 'A watch is sold at a loss of 12%. Had it been sold for ₹132 more, there would have been a gain of 10%. Find the cost price.', '["₹540","₹600","₹480","₹1200"]'::jsonb, 1, 'Difference of 22% of CP = ₹132, so CP = 132 × 100/22 = ₹600.', 'medium'),
('quant', 'profit-and-loss', 'A trader marks goods 25% above cost price and allows a discount of 25%. What is his profit or loss percentage?', '["8.25% profit","7.25% loss","0% profit","6.25% loss"]'::jsonb, 3, 'Take CP = 100. MP = 125, SP = 125 × 0.75 = 93.75. Loss = 6.25%.', 'medium'),
('quant', 'profit-and-loss', 'If the cost price of 12 articles equals the selling price of 10 articles, find the profit percentage.', '["16.67%","25%","20%","2%"]'::jsonb, 2, 'CP of 12 = SP of 10. Gain/loss on 10 articles = 2 articles'' CP. % = 2/10 × 100 = 20%.', 'medium'),
('quant', 'profit-and-loss', 'A watch is sold at a loss of 12%. Had it been sold for ₹504 more, there would have been a gain of 6%. Find the cost price.', '["₹2800","₹3080","₹1400","₹2240"]'::jsonb, 0, 'Difference of 18% of CP = ₹504, so CP = 504 × 100/18 = ₹2800.', 'medium'),
('quant', 'profit-and-loss', 'A trader marks goods 50% above cost price and allows a discount of 25%. What is his profit or loss percentage?', '["25% loss","25% profit","12.5% profit","13.5% loss"]'::jsonb, 2, 'Take CP = 100. MP = 150, SP = 150 × 0.75 = 112.5. Profit = 12.5%.', 'medium'),
('quant', 'profit-and-loss', 'If the cost price of 25 articles equals the selling price of 16 articles, find the profit percentage.', '["112.5%","36%","56.25%","61.25%"]'::jsonb, 2, 'CP of 25 = SP of 16. Gain/loss on 16 articles = 9 articles'' CP. % = 9/16 × 100 = 56.25%.', 'medium'),
('quant', 'profit-and-loss', 'A watch is sold at a loss of 12%. Had it been sold for ₹216 more, there would have been a gain of 6%. Find the cost price.', '["₹1080","₹1560","₹1200","₹1320"]'::jsonb, 2, 'Difference of 18% of CP = ₹216, so CP = 216 × 100/18 = ₹1200.', 'medium'),
('quant', 'profit-and-loss', 'A watch is sold at a loss of 10%. Had it been sold for ₹192 more, there would have been a gain of 6%. Find the cost price.', '["₹600","₹1200","₹1440","₹1080"]'::jsonb, 1, 'Difference of 16% of CP = ₹192, so CP = 192 × 100/16 = ₹1200.', 'medium'),
('quant', 'profit-and-loss', 'A trader marks goods 50% above cost price and allows a discount of 10%. What is his profit or loss percentage?', '["40% profit","36% loss","35% profit","37% profit"]'::jsonb, 2, 'Take CP = 100. MP = 150, SP = 150 × 0.9 = 135. Profit = 35%.', 'medium'),
('quant', 'profit-and-loss', 'If the cost price of 15 articles equals the selling price of 10 articles, find the profit percentage.', '["50%","55%","100%","5%"]'::jsonb, 0, 'CP of 15 = SP of 10. Gain/loss on 10 articles = 5 articles'' CP. % = 5/10 × 100 = 50%.', 'medium'),
('quant', 'profit-and-loss', 'A watch is sold at a loss of 12%. Had it been sold for ₹432 more, there would have been a gain of 6%. Find the cost price.', '["₹1920","₹2400","₹2640","₹1200"]'::jsonb, 1, 'Difference of 18% of CP = ₹432, so CP = 432 × 100/18 = ₹2400.', 'medium'),
('quant', 'profit-and-loss', 'If the cost price of 10 articles equals the selling price of 16 articles, find the loss percentage.', '["75%","37.5%","42.5%","60%"]'::jsonb, 1, 'CP of 10 = SP of 16. Gain/loss on 16 articles = 6 articles'' CP. % = 6/16 × 100 = 37.5%.', 'medium'),
('quant', 'profit-and-loss', 'A watch is sold at a loss of 12%. Had it been sold for ₹396 more, there would have been a gain of 10%. Find the cost price.', '["₹1800","₹900","₹1980","₹3600"]'::jsonb, 0, 'Difference of 22% of CP = ₹396, so CP = 396 × 100/22 = ₹1800.', 'medium'),
('quant', 'profit-and-loss', 'Two cycles are sold at the same price. One is sold at a 15% profit and the other at a 15% loss. What is the overall result?', '["15% loss","2.25% loss","2.25% profit","4.5% loss"]'::jsonb, 1, 'When two items are sold at the same price with equal % gain and loss, there is always a loss of (p²/100)% = 2.25%.', 'hard'),
('quant', 'profit-and-loss', 'A sells an item to B at 10% profit, and B sells it to C at 20% profit. If C pays ₹4620, what did A pay for it?', '["₹1750","₹3150","₹3500","₹2800"]'::jsonb, 2, 'CP of A × 1.1 × 1.2 = 4620. So A''s CP = ₹3500.', 'hard');
INSERT INTO aptitude_questions (section, topic_slug, question, options, answer_index, explanation, difficulty) VALUES
('quant', 'profit-and-loss', 'A dishonest dealer claims to sell at cost price but uses a weight of 950 g instead of 1 kg. What is his gain percentage?', '["3.76%","5.26%","5%","8%"]'::jsonb, 1, 'Gain% = error/(true value - error) × 100 = 50/950 × 100 = 5.26%.', 'hard'),
('quant', 'profit-and-loss', 'A sells an item to B at 10% profit, and B sells it to C at 10% profit. If C pays ₹3146, what did A pay for it?', '["₹2600","₹5200","₹2860","₹2340"]'::jsonb, 0, 'CP of A × 1.1 × 1.1 = 3146.000000000001. So A''s CP = ₹2600.', 'hard'),
('quant', 'profit-and-loss', 'A sells an item to B at 25% profit, and B sells it to C at 10% profit. If C pays ₹4400, what did A pay for it?', '["₹3520","₹2560","₹3200","₹6400"]'::jsonb, 2, 'CP of A × 1.25 × 1.1 = 4400. So A''s CP = ₹3200.', 'hard'),
('quant', 'profit-and-loss', 'A dishonest dealer claims to sell at cost price but uses a weight of 960 g instead of 1 kg. What is his gain percentage?', '["7%","2.67%","4.17%","4%"]'::jsonb, 2, 'Gain% = error/(true value - error) × 100 = 40/960 × 100 = 4.17%.', 'hard'),
('quant', 'profit-and-loss', 'Two cycles are sold at the same price. One is sold at a 12% profit and the other at a 12% loss. What is the overall result?', '["2.88% loss","1.44% loss","No profit no loss","12% loss"]'::jsonb, 1, 'When two items are sold at the same price with equal % gain and loss, there is always a loss of (p²/100)% = 1.44%.', 'hard'),
