('quant', 'averages', 'The average of 13 numbers is 33. If one number is removed, the average of the rest becomes 31. What number was removed?', '["57","69","63","28.5"]'::jsonb, 0, 'Removed = 13×33 - 12×31 = 429 - 372 = 57.', 'medium'),
('quant', 'averages', 'A batsman scores 81 runs in his 20th innings and thereby increases his average by 3. What is his average after the 20th innings?', '["21","27","24","4.05"]'::jsonb, 2, 'New average = score - (innings - 1) × increase = 81 - 19×3 = 24.', 'medium');
INSERT INTO aptitude_questions (section, topic_slug, question, options, answer_index, explanation, difficulty) VALUES
('quant', 'averages', 'The average marks of 13 students in section A is 60 and of 12 students in section B is 65. Find the combined average.', '["63.9","65","62.5","62.4"]'::jsonb, 3, '(13×60 + 12×65)/(25) = 62.4.', 'medium'),
