INSERT INTO aptitude_questions (section, topic_slug, question, options, answer_index, explanation, difficulty) VALUES
('logical', 'coding-and-decoding', 'If MILK is coded as NHMJ, how is SALT coded?', '["TBMU","TZMS","SMZT","RBKU"]'::jsonb, 1, 'Letters in odd positions move +1, letters in even positions move -1. SALT → TZMS.', 'medium'),
('logical', 'coding-and-decoding', 'If FISH = 42 (A = 1, B = 2, ...), what is BOOK?', '["51","21.5","43","47"]'::jsonb, 2, 'Add the alphabet positions: B=2, O=15, O=15, K=11 → 43.', 'medium'),
('logical', 'coding-and-decoding', 'If KING is coded as LHOF, how is SALT coded?', '["RZKS","RBKU","TZMS","TBMU"]'::jsonb, 2, 'Letters in odd positions move +1, letters in even positions move -1. SALT → TZMS.', 'medium'),
('logical', 'coding-and-decoding', 'If LAMP = 42 (A = 1, B = 2, ...), what is KING?', '["41","20.5","37","45"]'::jsonb, 0, 'Add the alphabet positions: K=11, I=9, N=14, G=7 → 41.', 'medium'),
