('logical', 'calendars', '1 January 2015 was a Thursday. What day of the week was 1 January 2016?', '["Tuesday","Sunday","Monday","Friday"]'::jsonb, 3, '2015 has 365 days = 1 odd day. Thursday + 1 = Friday.', 'medium'),
('logical', 'calendars', 'If 1 October 2026 is a Thursday, what day is 17 October 2026?', '["Wednesday","Tuesday","Monday","Saturday"]'::jsonb, 3, '16 days after the 1st: (16) mod 7 = 2. Thursday + 2 = Saturday.', 'medium'),
('logical', 'calendars', 'If 1 September 2006 is a Friday, what day is 15 September 2006?', '["Friday","Monday","Sunday","Thursday"]'::jsonb, 0, '14 days after the 1st: (14) mod 7 = 0. Friday + 0 = Friday.', 'medium'),
('logical', 'calendars', '1 January 2033 was a Saturday. What day of the week was 1 January 2034?', '["Thursday","Sunday","Saturday","Friday"]'::jsonb, 1, '2033 has 365 days = 1 odd day. Saturday + 1 = Sunday.', 'medium'),
('logical', 'calendars', 'If 1 December 2025 is a Monday, what day is 18 December 2025?', '["Thursday","Monday","Saturday","Tuesday"]'::jsonb, 0, '17 days after the 1st: (17) mod 7 = 3. Monday + 3 = Thursday.', 'medium'),
('logical', 'calendars', '1 January 2000 was a Saturday. What day of the week was 1 January 2001?', '["Sunday","Friday","Monday","Wednesday"]'::jsonb, 2, '2000 has 366 days = 2 odd days. Saturday + 2 = Monday.', 'medium'),
('logical', 'calendars', 'If 1 December 2026 is a Tuesday, what day is 15 December 2026?', '["Saturday","Wednesday","Tuesday","Monday"]'::jsonb, 2, '14 days after the 1st: (14) mod 7 = 0. Tuesday + 0 = Tuesday.', 'medium'),
('logical', 'calendars', '1 January 2020 was a Wednesday. What day of the week was 1 January 2021?', '["Monday","Friday","Thursday","Wednesday"]'::jsonb, 1, '2020 has 366 days = 2 odd days. Wednesday + 2 = Friday.', 'medium'),
('logical', 'calendars', 'If 1 February 2003 is a Saturday, what day is 27 February 2003?', '["Sunday","Thursday","Friday","Monday"]'::jsonb, 1, '26 days after the 1st: (26) mod 7 = 5. Saturday + 5 = Thursday.', 'medium'),
('logical', 'calendars', 'The calendar of the year 2004 can be used again in which year?', '["2032","2031","2011","2033"]'::jsonb, 0, 'We need a year starting on the same day (Thursday) with the same leap status. Counting odd days forward, the first such year is 2032.', 'hard'),
('logical', 'calendars', 'What day of the week was 15 May 2029?', '["Saturday","Monday","Sunday","Tuesday"]'::jsonb, 3, 'Count odd days: years before 2029, months before May, then 15 days. Total odd days mod 7 = 2 → Tuesday (0 = Sunday).', 'hard'),
('logical', 'calendars', 'The calendar of the year 2002 can be used again in which year?', '["2012","2008","2009","2013"]'::jsonb, 3, 'We need a year starting on the same day (Tuesday) with the same leap status. Counting odd days forward, the first such year is 2013.', 'hard'),
('logical', 'calendars', 'What day of the week was 19 April 2001?', '["Friday","Wednesday","Thursday","Tuesday"]'::jsonb, 2, 'Count odd days: years before 2001, months before April, then 19 days. Total odd days mod 7 = 4 → Thursday (0 = Sunday).', 'hard'),
('logical', 'calendars', 'The calendar of the year 2001 can be used again in which year?', '["2012","2007","2006","2008"]'::jsonb, 1, 'We need a year starting on the same day (Monday) with the same leap status. Counting odd days forward, the first such year is 2007.', 'hard'),
('logical', 'calendars', 'What day of the week was 21 June 2007?', '["Wednesday","Monday","Tuesday","Thursday"]'::jsonb, 3, 'Count odd days: years before 2007, months before June, then 21 days. Total odd days mod 7 = 4 → Thursday (0 = Sunday).', 'hard'),
('logical', 'calendars', 'The calendar of the year 2021 can be used again in which year?', '["2028","2027","2026","2032"]'::jsonb, 1, 'We need a year starting on the same day (Friday) with the same leap status. Counting odd days forward, the first such year is 2027.', 'hard'),
('logical', 'calendars', 'What day of the week was 6 December 1953?', '["Saturday","Friday","Thursday","Sunday"]'::jsonb, 3, 'Count odd days: years before 1953, months before December, then 6 days. Total odd days mod 7 = 0 → Sunday (0 = Sunday).', 'hard'),
('logical', 'calendars', 'The calendar of the year 2022 can be used again in which year?', '["2029","2033","2028","2034"]'::jsonb, 1, 'We need a year starting on the same day (Saturday) with the same leap status. Counting odd days forward, the first such year is 2033.', 'hard'),
('logical', 'calendars', 'What day of the week was 26 October 1959?', '["Thursday","Friday","Wednesday","Monday"]'::jsonb, 3, 'Count odd days: years before 1959, months before October, then 26 days. Total odd days mod 7 = 1 → Monday (0 = Sunday).', 'hard'),
('logical', 'calendars', 'The calendar of the year 2015 can be used again in which year?', '["2026","2027","2022","2021"]'::jsonb, 0, 'We need a year starting on the same day (Thursday) with the same leap status. Counting odd days forward, the first such year is 2026.', 'hard'),
('logical', 'calendars', 'What day of the week was 3 July 1972?', '["Saturday","Friday","Monday","Wednesday"]'::jsonb, 2, 'Count odd days: years before 1972, months before July, then 3 days. Total odd days mod 7 = 1 → Monday (0 = Sunday).', 'hard'),
('logical', 'calendars', 'The calendar of the year 2027 can be used again in which year?', '["2039","2037","2038","2034"]'::jsonb, 2, 'We need a year starting on the same day (Friday) with the same leap status. Counting odd days forward, the first such year is 2038.', 'hard'),
