((SELECT id FROM companies WHERE slug = 'freshworks'), 'roles', 'Typical fresher roles', '["Software Engineer / SDE-1","Software Engineering Intern (for pre-final years)","Data / ML Engineer (team-dependent)","Quality / Test Engineer (some teams)"]'::jsonb, 'guidance', 0),
((SELECT id FROM companies WHERE slug = 'freshworks'), 'eligibility', 'Eligibility (not verified)', '["BrainBridge has NOT verified current eligibility criteria for Freshworks.","Criteria such as CGPA/percentage cut-offs, active backlogs, education gaps and eligible branches can change for every drive.","Always check the official careers page (https://careers.freshworks.com/) and your college placement cell for the current notification."]'::jsonb, 'not_verified', 1),
((SELECT id FROM companies WHERE slug = 'freshworks'), 'stages', 'Recruitment stages (general guidance)', '["Online assessment: 2-3 coding problems (sometimes with MCQs on CS fundamentals).","2-4 technical interviews: DSA problem solving, code quality, complexity, CS fundamentals and projects.","Some roles: design / low-level design or machine-coding round.","Behavioural / hiring-manager round on teamwork, ownership and motivation.","Expect coding plus design discussion for SDE roles."]'::jsonb, 'guidance', 2),
((SELECT id FROM companies WHERE slug = 'freshworks'), 'technical', 'Technical topics to focus on', '["DSA","OOP and LLD","Web fundamentals","Operating systems, DBMS and networks fundamentals","Project architecture and trade-offs"]'::jsonb, 'guidance', 3),
((SELECT id FROM companies WHERE slug = 'freshworks'), 'coding', 'Coding preparation', '["Solve the BrainBridge coding bank Medium and Hard problems (graphs, DP, heaps, sliding window).","Practise explaining your approach aloud before coding.","Always state time and space complexity and test edge cases.","Time yourself: ~25-30 minutes per medium problem."]'::jsonb, 'guidance', 4),
((SELECT id FROM companies WHERE slug = 'freshworks'), 'aptitude', 'Aptitude preparation', '["Aptitude is usually a smaller part for product companies; focus on probability, permutations and logical puzzles.","Use BrainBridge Quant → Probability and P&C quizzes."]'::jsonb, 'guidance', 5),
((SELECT id FROM companies WHERE slug = 'freshworks'), 'interview', 'Interview patterns (general guidance)', '["Clarify the problem → discuss brute force → optimise → code → test.","Interviewers value communication as much as the final code.","Be ready to go deep on one project you built.","Ask clarifying questions about constraints and edge cases."]'::jsonb, 'guidance', 6),
((SELECT id FROM companies WHERE slug = 'freshworks'), 'hr', 'Common HR questions to prepare', '["Tell me about yourself.","Why do you want to join Freshworks?","What are your strengths and weaknesses?","Describe a challenge you faced in a team project.","Tell me about a time you took ownership beyond your assigned work.","Where do you see yourself in five years?"]'::jsonb, 'guidance', 7),
((SELECT id FROM companies WHERE slug = 'freshworks'), 'roadmap', '4-week preparation roadmap', '["Week 1: Arrays, strings, hashing, two pointers, sliding window (BrainBridge DSA + Easy/Medium problems).","Week 2: Linked lists, stacks, queues, trees, BST, heaps.","Week 3: Graphs, DP, greedy, backtracking + 2 mock interviews (SDE track).","Week 4: CS fundamentals revision, project deep-dive, behavioural STAR stories, final mocks."]'::jsonb, 'guidance', 8),
((SELECT id FROM companies WHERE slug = 'freshworks'), 'resources', 'Recommended resources', '["Official careers site: https://careers.freshworks.com/","BrainBridge: Learning Roadmap, Aptitude quizzes, Coding bank, Interview Preparation and Mock Interviews.","Your college placement cell and alumni from the company for current-year process details."]'::jsonb, 'guidance', 9),
((SELECT id FROM companies WHERE slug = 'freshworks'), 'practice', 'Representative practice (original BrainBridge questions)', '["These are NOT previous-year questions — they are original BrainBridge practice items on the same topics.","Coding: try \"Pair with Target Sum\", \"Count the Islands\", \"Longest Rising Sequence\" and \"City Road Distances\" in the coding bank.","Aptitude: Probability and Permutations & Combinations quizzes (Hard).","Interview: take the matching mock interview track and review the rubric feedback."]'::jsonb, 'guidance', 10),
((SELECT id FROM companies WHERE slug = 'tcs'), 'roles', 'Typical fresher roles', '["Software Engineer / Programmer Analyst / Associate (title varies)","Higher-tier digital/specialist roles (based on test performance)","Graduate Engineer Trainee","Consulting / Business Analyst roles (some firms)"]'::jsonb, 'guidance', 0),
((SELECT id FROM companies WHERE slug = 'tcs'), 'eligibility', 'Eligibility (not verified)', '["BrainBridge has NOT verified current eligibility criteria for TCS (Tata Consultancy Services).","Criteria such as CGPA/percentage cut-offs, active backlogs, education gaps and eligible branches can change for every drive.","Always check the official careers page (https://www.tcs.com/careers) and your college placement cell for the current notification."]'::jsonb, 'not_verified', 1),
((SELECT id FROM companies WHERE slug = 'tcs'), 'stages', 'Recruitment stages (general guidance)', '["Online test: quantitative aptitude, logical reasoning, verbal ability; often a coding or pseudo-code section.","Technical interview: programming basics, OOP, DBMS/SQL, OS/CN basics, and your project.","HR interview: communication, attitude, relocation and shift flexibility.","Some firms include a communication/English assessment or group discussion.","Fresher hiring has commonly used the TCS National Qualifier Test (NQT), with role tiers based on performance. Check the official site for the current process."]'::jsonb, 'guidance', 2),
((SELECT id FROM companies WHERE slug = 'tcs'), 'technical', 'Technical topics to focus on', '["Aptitude (numerical, reasoning, verbal)","Basic coding in any language","Fundamentals (OOP, DBMS, OS)","OOP concepts with examples","SQL queries (joins, group by, subqueries)"]'::jsonb, 'guidance', 3),
((SELECT id FROM companies WHERE slug = 'tcs'), 'coding', 'Coding preparation', '["Master Easy problems in one language: arrays, strings, loops, patterns.","Practise reading and tracing pseudo-code and predicting output.","Learn basic recursion, sorting and searching.","Attempt Medium problems once Easy problems feel comfortable."]'::jsonb, 'guidance', 4),
((SELECT id FROM companies WHERE slug = 'tcs'), 'aptitude', 'Aptitude preparation', '["Quant: percentages, profit & loss, time & work, TSD, ratios, averages, P&C, probability.","Logical: series, coding-decoding, blood relations, seating arrangements, syllogisms.","Verbal: reading comprehension, sentence correction, fill in the blanks.","Take full timed BrainBridge assessments weekly and review mistakes."]'::jsonb, 'guidance', 5),
((SELECT id FROM companies WHERE slug = 'tcs'), 'interview', 'Interview patterns (general guidance)', '["Self-introduction followed by questions on your strongest language.","Explain OOP pillars, DBMS normalisation, SQL joins with examples.","Write simple programs on paper/screen (palindrome, Fibonacci, sorting).","Project walkthrough: your role, tech stack and challenges."]'::jsonb, 'guidance', 6),
((SELECT id FROM companies WHERE slug = 'tcs'), 'hr', 'Common HR questions to prepare', '["Tell me about yourself.","Why do you want to join TCS (Tata Consultancy Services)?","What are your strengths and weaknesses?","Describe a challenge you faced in a team project.","Are you willing to relocate and work in shifts?","Where do you see yourself in five years?"]'::jsonb, 'guidance', 7),
((SELECT id FROM companies WHERE slug = 'tcs'), 'roadmap', '4-week preparation roadmap', '["Week 1: Quant aptitude daily quizzes + programming basics in your language.","Week 2: Logical reasoning + verbal ability + OOP and DBMS lessons.","Week 3: Full timed assessments + easy coding problems + SQL practice.","Week 4: HR answers, communication exercises, mock interviews and resume final check."]'::jsonb, 'guidance', 8),
